/**
 * Field projections for reconstructed V4 regression inputs, including deliberately malformed
 * copies. These types provide no evidence: maintained validators check the generated byte set.
 * The scoped unit fixtures do not claim recovery of the missing historical execution archive.
 */

/** Executor path fields supplied by the maintained contract within the isolated unit-test graph. */
export interface ExecutorPathFixture {
  /** Original frozen authority directory. */
  frozenAuthorityRoot: string;
  /** Original frozen authority trace. */
  frozenAuthorityTrace: string;
  /** Original executor source filename. */
  executor: string;
  /** Approved process working directory. */
  workingDirectory: string;
  /** Existing parent of the future profile root. */
  existingParent: string;
  /** Reserved profile output directory. */
  profileRoot: string;
  /** Reserved trace filename. */
  trace: string;
  /** Official validator filename. */
  validator: string;
}

/** Only imported identities directly read while constructing these test fixtures. */
export interface ExecutorBindingFixture {
  /** SHA-256 of the original frozen authority. */
  frozenAuthoritySha256: string;
  /** SHA-256 of the reviewed plan. */
  planSha256: string;
  /** SHA-256 of the approved production manifest. */
  productionManifestSha256: string;
}

/** Existing materialization vector starts with the Node executable. */
export type ExecutorArgumentFixture = readonly [string, ...string[]];

/** Projection of the hash fields changed by attempt and terminal negative cases. */
export interface ExecutorHashFixture extends Record<string, unknown> {
  /** Hash of the executor source. */
  executorSha256: string;
  /** Hash of the route-pattern regression source. */
  routePatternTestSha256: string;
}

/** Runnable entry fields rewritten while deriving the repaired copy of the original trace. */
export interface RunnableAuthorityFixture extends Record<string, unknown> {
  /** Original route identity used by duplicate references. */
  id: string;
  /** Discriminator used before any runnable-only field is accessed. */
  disposition: 'runnable';
  /** Original captured parameter values. */
  parameters: Record<string, unknown>;
  /** Concrete authored route pathname. */
  pathname: string;
  /** Replay values updated to match the repaired route. */
  replay: Record<string, unknown> & {
    parameters: Record<string, unknown>;
    pathname: string;
  };
  /** Existing execution plan whose route values and digest are rebound in the fixture. */
  executionPlan: Record<string, unknown> & {
    recipe: Record<string, unknown> & {
      params: Record<string, unknown>;
      pathname: string;
    };
    selectedBranch: Record<string, unknown> & { pathname: string };
    digest: string;
  };
}

/** Duplicate references use only these values from their original runnable target. */
export type RunnableTargetFixture = Pick<
  RunnableAuthorityFixture,
  'parameters' | 'pathname' | 'replay'
>;

/** Duplicate entry fields copied from its original runnable target. */
interface DuplicateAuthorityFixture extends Record<string, unknown> {
  /** Duplicate discriminator used before resolving its target. */
  disposition: 'duplicate';
  /** Runnable identity referenced by this original duplicate. */
  duplicateOf: string;
  /** Parameters replaced by a clone of the repaired target's values. */
  parameters: Record<string, unknown>;
  /** Pathname replaced by the repaired target's pathname. */
  pathname: string;
  /** Replay replaced by a clone of the repaired target's replay. */
  replay: RunnableAuthorityFixture['replay'];
}

/** Unresolved entries pass unchanged through the repair loops. */
interface UnresolvedAuthorityFixture extends Record<string, unknown> {
  /** Discriminator excluded by both runnable and duplicate repair loops. */
  disposition: 'unresolved';
}

/** Original terminal inventory container selected by the fixture's final-record lookup. */
export interface AuthorityTerminalFixture {
  /** Existing route entries; no replacement authority is constructed by this type. */
  inventory: {
    entries: (RunnableAuthorityFixture | DuplicateAuthorityFixture | UnresolvedAuthorityFixture)[];
  };
}

/** Original authority has a header; later records remain unknown until the terminal projection. */
export type AuthorityRecordsFixture = [Record<string, unknown>, ...unknown[]];

/** Fields changed by the reviewed-preflight negative cases. */
export interface ReviewedPreflightFixture extends Record<string, unknown> {
  /** Original review decision. */
  solReview: { status: string };
  /** Current route-pattern test identity. */
  identities: { routePatternTest: { sha256: string } };
  /** Recorded dependency-view link count. */
  snapshot: { dependencyView: { linkCount: number } };
  /** Frozen trace newline observation. */
  frozenLineage: { authorityTrace: { finalLf: boolean } };
  /** Approved invocation has at least the four positions accessed by these cases. */
  invocation: { argumentVector: [string, string, string, string, ...string[]] };
  /** Recorded count of matching live processes. */
  observedZeroState: { matchingProcessCount: number };
}

/** Local callable view; the maintained executor contract supplies and validates every fact. */
export type ProspectivePreflightFixtureBuilder = (
  state: unknown,
  executorSha256: string,
) => Record<string, unknown>;

/** Original attempt marker fields changed by the negative cases. */
export interface AttemptStartFixture extends Record<string, unknown> {
  /** Completion marker before a case corrupts it. */
  complete: boolean;
  /** Fixed three-token executor command in the authored test fixture. */
  command: Record<string, unknown> & { argumentVector: [string, string, string] };
  /** Existing code identities, copied from the production helper. */
  hashBindings: ExecutorHashFixture;
  /** Original root-creation policy. */
  directRootContract: Record<string, unknown> & { executorCreatesRoot: boolean };
  /** Original count before any profile spawn. */
  profileSpawnApiInvocationCount: number;
}

/** Process observation fields read or corrupted by the terminal test cases. */
export interface ProcessInspectionFixture extends Record<string, unknown> {
  /** Number of exact matching processes. */
  exactMatchingCount: number;
  /** Observed matching process IDs. */
  matchedPids: number[];
}

/** Stream identity used by both separated streams and tagged callback records. */
interface StreamFixture {
  /** Number of raw bytes. */
  byteCount: number;
  /** Canonical base64 encoding of the raw bytes. */
  base64: string;
  /** SHA-256 of the raw bytes. */
  sha256: string;
}

/** Only terminal fields exercised by the existing negative cases; other serialized fields stay unknown. */
export interface TerminalEvidenceFixture extends Record<string, unknown> {
  /** Existing executor and route-pattern identities. */
  hashBindings: ExecutorHashFixture;
  /** Reviewed-preflight identity whose byte count can be corrupted. */
  reviewedPreflightIdentity: Record<string, unknown> & { byteCount: number };
  /** Attempt identity whose hash can be corrupted. */
  attemptStartIdentity: Record<string, unknown> & { sha256: string };
  /** Recorded child-materialization decision. */
  materialization: Record<string, unknown> & { authorizedChildMaterialized: boolean };
  /** Existing lifecycle observations and the three authored spawn, exit, and close events. */
  execution: Record<string, unknown> & {
    profileSpawnApiInvocationCount: number;
    exitCode: number;
    signal: string | null;
    closeObserved: boolean;
    durationNanoseconds: string;
    events: [
      Record<string, unknown> & { sequence: number },
      Record<string, unknown> & { sequence: number },
      Record<string, unknown> & { sequence: number },
    ];
  };
  /** Existing separated stream records and callback order. */
  streams: Record<string, unknown> & {
    stdout: StreamFixture;
    stderr: StreamFixture;
    taggedCallbackOrder: (StreamFixture & { sequence: number; stream: string })[];
  };
  /** Original pre-execution root observation. */
  preState: Record<string, unknown> & {
    profileRoot: Record<string, unknown> & { exists: boolean };
  };
  /** Original post-execution root and process observations. */
  postStateResult: Record<string, unknown> & {
    value: Record<string, unknown> & {
      profileRoot: Record<string, unknown> & { type: string };
      processInspection: ProcessInspectionFixture;
    };
  };
  /** Original generated trace identity. */
  traceResult: Record<string, unknown> & {
    value: Record<string, unknown> & { sha256: string };
  };
  /** Whether post-child inspection failed. */
  postChildInspectionFailure: boolean;
  /** Browser execution remains a forbidden action until a case deliberately forges it. */
  prohibitedActions: Record<string, unknown> & { browserExecuted: boolean };
  /** Strict-audit observation before its negative mutation. */
  audit: Record<string, unknown> & { strict681AuditPerformed: boolean };
}

/** Only the validated terminal decision inspected by the positive schema test. */
export interface TerminalResultFixture {
  /** Production validator's terminal outcome. */
  result: string;
}

/** Compact report fields changed or inspected by the historical schema cases. */
export interface CompactValidationFixture extends Record<string, unknown> {
  /** Original authority line count. */
  authority: { lineCount: number };
  /** Original no-go release decision before a case corrupts it. */
  releaseResult: string;
  /** Fixed historical authority contains eighteen unresolved blockers. */
  unresolvedBlockers: [Record<string, unknown> & { reason: string }, ...unknown[]];
  /** Runnable count before a case corrupts it. */
  inventoryCounts: { runnable: number };
}

/** Only context fields changed by the before-write run-binding drift cases. */
export interface RunContextMutationFixture {
  /** Existing validator process tokens, including the official mode at position two. */
  invocation: { argv: [string, string, string, ...string[]] };
  /** Existing ordered identities, including the consumed-attempt identity at position six. */
  bindings: [
    { path: string },
    { path: string },
    { path: string },
    { path: string },
    { path: string },
    { path: string },
    { path: string },
    ...{ path: string }[],
  ];
}
